/* Child-Safer Spaces · offline copy for hosted use · generated by source/build.cjs.
 * Caches the workspace files (never planning data) so a hosted copy opens without a connection.
 * Only same-origin GET requests are answered; nothing is sent anywhere. */
'use strict';
const CACHE = 'child-safer-spaces-4.0-e4c07b38fd8f';
const FILES = ["./","index.html","style.css","data.js","core.js","store.js","atmosphere.js","app.js","icon.svg","app.webmanifest","handbook.html"];
self.addEventListener('install', e => { e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES)).then(() => self.skipWaiting())); });
self.addEventListener('activate', e => { e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith('child-safer-spaces-') && k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim())); });
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  e.respondWith(caches.open(CACHE).then(c => c.match(req, { ignoreSearch: true }).then(hit => hit || (req.mode === 'navigate' ? c.match('index.html') : undefined)).then(hit => hit || fetch(req))));
});
